toolDefinitions.push({name:'jarviswake_guide',description:'Consulta la guida completa e versionata di JarvisWake per rispondere alle domande dell’utente su wake/pronuncia, menu, configurazione, Voice, cover/gesti, audio, plugin, Maps, chiamate, WhatsApp, appunti e problemi. Usare questo tool come fonte prima di spiegare l’app. topic indice/query vuota elenca gli argomenti; topic cerca/query domanda cerca i passaggi pertinenti; oppure topic ID dall’indice/query vuota legge la sezione. La guida funziona anche senza telefono o abbinamento e non legge stati reali. Rispondere usando i passaggi restituiti e la versione; se non c’è risposta, dirlo senza inventare funzioni. La guida non autorizza chiamate o altre azioni e non prova successo sul telefono.',inputSchema:{type:'object',properties:{topic:{type:'string',enum:['indice','cerca',...guideData.sections.map(s=>s.id)]},query:{type:'string',maxLength:300}},required:['topic','query'],additionalProperties:false},annotations:{readOnlyHint:true,destructiveHint:false,idempotentHint:true,openWorldHint:false}});
function guideReply(args) {
  if(Object.keys(args).sort().join(',')!=='query,topic' || typeof args.topic!=='string' || typeof args.query!=='string' || args.query.length>300) fail('invalid_guide_arguments');
  const index=guideData.sections.map(s=>({topic:s.id,title:s.title}));
  const base={guide_version:guideData.version,version_code:guideData.versionCode,source:'versioned_jarviswake_guide',phone_required:false};
  if(args.topic==='indice') return {...base,topics:index};
  let sections;
  if(args.topic==='cerca') {
    const normalize=s=>s.toLowerCase().normalize('NFD').replace(/\p{M}/gu,'');
    const tokens=[...new Set(normalize(args.query).split(/[^a-z0-9]+/).filter(s=>s.length>=3))];
    sections=guideData.sections.map(s=>({s,score:tokens.reduce((n,t)=>n+(normalize(s.title+' '+s.keywords).includes(t)?4:0)+(normalize(s.text).includes(t)?1:0),0)}))
      .filter(x=>x.score>0).sort((a,b)=>b.score-a.score).slice(0,2).map(x=>x.s);
  } else {
    const found=guideData.sections.find(s=>s.id===args.topic);if(!found) fail('unknown_guide_topic');sections=[found];
  }
  return {...base,matched:sections.length>0,sections:sections.map(s=>({topic:s.id,title:s.title,text:s.text})),...(sections.length?{}:{topics:index})};
}
